import { operation, resource, tag } from "@tinker/core";
import { z } from "zod";
import type { BetterAuthPlugin } from "better-auth";
import { database } from "./database.ts";
import { sendMail } from "./mail.ts";
import { raise } from "../errors.ts";
export declare namespace Auth {
  type Settings = {
    origin: string | { allowedHosts: string[]; fallback: string };
    secret: string;
    plugins: BetterAuthPlugin[];
  };
}
export const authSettings = tag<Auth.Settings>({ label: "auth.settings" });
export const requestHeaders = tag<Headers>({ label: "request.headers" });
export const auth = resource({
  label: "auth",
  target: "session",
  depends: { database, settings: authSettings, send: sendMail },
  factory: async ({ database, settings, send }) => {
    const [{ betterAuth }, { drizzleAdapter }, schema] = await Promise.all([
      import("better-auth"),
      import("better-auth/adapters/drizzle"),
      import("./schema.ts"),
    ]);
    return betterAuth({
      baseURL: settings.origin,
      secret: settings.secret,
      database: drizzleAdapter(database, { provider: "pg", schema }),
      emailAndPassword: {
        enabled: true,
        sendResetPassword: async ({ user, url }) => {
          await send.run({ input: { to: user.email, subject: "Reset your password", text: url } });
        },
      },
      emailVerification: {
        sendOnSignUp: true,
        sendVerificationEmail: async ({ user, url }) => {
          await send.run({ input: { to: user.email, subject: "Check your email", text: url } });
        },
      },
      plugins: settings.plugins,
    });
  },
});
export const handleAuth = operation({
  label: "handleAuth",
  input: z.instanceof(Request),
  depends: { auth },
  run: async ({ auth }, ctx) => auth.handler(ctx.input),
});
export const principal = resource({
  label: "request.principal",
  target: "session",
  depends: { auth, headers: requestHeaders },
  factory: async ({ auth, headers }) => (await auth.api.getSession({ headers }))?.user ?? null,
});
export const currentUser = resource({
  label: "request.currentUser",
  target: "session",
  depends: { principal },
  factory: async ({ principal }) => {
    if (principal === null) raise("SignInRequired", {});
    return principal;
  },
});
export const readAccount = operation({
  label: "readAccount",
  depends: { principal },
  run: async ({ principal }) => principal?.id ?? null,
});

import { operation } from "@tinker/core";
import { database } from "./database.ts";
import { eventHistory } from "../scaffold/backend/events.ts";
import { readExecution } from "../contracts/sync.ts";
import { raise } from "../errors.ts";
export const incrementCounter = operation({
  label: "incrementCounter",
  input: readExecution,
  depends: { database, history: eventHistory },
  run: async ({ database, history }, ctx) => {
    const [{ eq, sql }, { counter }, { execution }] = await Promise.all([
      import("drizzle-orm"),
      import("./sync.schema.ts"),
      import("../scaffold/backend/sync.schema.ts"),
    ]);
    await database.transaction(async (tx) => {
      await history.lock(tx, "public");
      if (await history.find(tx, ctx.input.executionId, "public")) return;
      await tx.insert(execution).values({ id: ctx.input.executionId, stream: "public" });
      await tx.insert(counter).values({ id: 1 }).onConflictDoNothing();
      const row = (
        await tx
          .update(counter)
          .set({ value: sql`${counter.value} + 1` })
          .where(eq(counter.id, 1))
          .returning()
      ).at(0);
      if (!row) raise("StreamMissing", {});
      await history.append(tx, "public", ctx.input.executionId, [
        { kind: "change", change: { kind: "counter", value: row.value } },
        { kind: "result", result: { kind: "complete", action: "counter" } },
      ]);
    });
    return { executionId: ctx.input.executionId };
  },
});

import { operation, resource, tag } from "@tinker/core";
import type { Database } from "../scaffold/backend/database.ts";
export type { Database } from "../scaffold/backend/database.ts";
export const databaseSettings = tag<{ url: string; migrations: string }>({
  label: "database.settings",
});
/** Feature code uses native PostgreSQL queries, without the driver's client field. */
export const database = resource({
  label: "database",
  depends: { settings: databaseSettings },
  factory: async ({ settings }, ctx): Promise<Database.Handle> => {
    const [{ default: pg }, { drizzle }] = await Promise.all([
      import("pg"),
      import("drizzle-orm/node-postgres"),
    ]);
    const client = new pg.Pool({ connectionString: settings.url });
    ctx.defer(() => client.end());
    return Object.assign(drizzle({ client }), {
      async listen(wake: () => void, disconnected: () => void) {
        const listener = await client.connect();
        listener.on("notification", wake);
        listener.on("error", disconnected);
        listener.on("end", disconnected);
        let released = false;
        const close = async () => {
          if (released) return;
          released = true;
          listener.removeListener("notification", wake);
          listener.removeListener("error", disconnected);
          listener.removeListener("end", disconnected);
          listener.release(true);
        };
        try {
          await listener.query("LISTEN start_sync");
          return close;
        } catch (error) {
          await close();
          throw error;
        }
      },
    });
  },
});
export const migrate = operation({
  label: "migrate",
  depends: { database, settings: databaseSettings },
  run: async ({ database, settings }) => {
    const [{ migrate }, { readMigrationFiles }] = await Promise.all([
      import("drizzle-orm/pg-core"),
      import("drizzle-orm/migrator"),
    ]);
    await migrate(readMigrationFiles({ migrationsFolder: settings.migrations }), database, {
      migrationsFolder: settings.migrations,
    });
  },
});

