import { pgTable, integer } from "drizzle-orm/pg-core";
export const counter = pgTable("public_counter", {
  id: integer().primaryKey(),
  value: integer().notNull().default(0),
});

import { operation } from "@tinker/core";
import { database } from "./database.ts";
import { currentUser, principal } from "./auth.ts";
import { eventHistory } from "../scaffold/backend/events.ts";
import { readCursor, readPrivateCursor, readFeatureEvent } from "../contracts/sync.ts";
import type { Sync } from "../contracts/sync.ts";
import { raise } from "../errors.ts";
export const bootstrapPublic = operation({
  label: "bootstrapPublic",
  depends: { database, history: eventHistory },
  run: async ({ database, history }) => {
    const { counter } = await import("./sync.schema.ts");
    return database.transaction(async (tx) => {
      const revision = await history.lock(tx, "public");
      return {
        stream: "public" as const,
        revision,
        value: (await tx.select().from(counter)).at(0)?.value ?? 0,
      };
    });
  },
});
export const bootstrapPrivate = operation({
  label: "bootstrapPrivate",
  depends: { currentUser, database, history: eventHistory },
  run: async ({ currentUser, database, history }) => {
    const [{ eq, asc }, { user }, { todo }] = await Promise.all([
      import("drizzle-orm"),
      import("./schema.ts"),
      import("./todos.schema.ts"),
    ]);
    return database.transaction(async (tx) => {
      const revision = await history.lock(tx, currentUser.id);
      const profile = (
        await tx
          .select({
            id: user.id,
            name: user.name,
            email: user.email,
            emailVerified: user.emailVerified,
          })
          .from(user)
          .where(eq(user.id, currentUser.id))
      ).at(0);
      if (!profile) raise("SignInRequired", {});
      const todos = await tx
        .select({ id: todo.id, title: todo.title, done: todo.done })
        .from(todo)
        .where(eq(todo.ownerId, currentUser.id))
        .orderBy(asc(todo.id));
      return { stream: currentUser.id, revision, profile, todos };
    });
  },
});
export const bootstrap = operation({
  label: "bootstrap",
  depends: { principal, public: bootstrapPublic, private: bootstrapPrivate },
  run: async ({
    principal,
    public: publicState,
    private: privateState,
  }): Promise<Sync.Snapshot> => ({
    public: await publicState.run(),
    private: principal === null ? null : await privateState.run(),
  }),
});
export const replayPublic = operation({
  label: "replayPublic",
  input: readCursor,
  depends: { database, principal },
  run: async ({ database, principal }, ctx) => {
    const [{ and, eq, gt, asc }, { event }] = await Promise.all([
      import("drizzle-orm"),
      import("../scaffold/backend/sync.schema.ts"),
    ]);
    return {
      accountId: principal?.id ?? null,
      events: (
        await database
          .select()
          .from(event)
          .where(and(eq(event.stream, "public"), gt(event.revision, ctx.input.after)))
          .orderBy(asc(event.revision))
          .limit(200)
      ).map(readFeatureEvent),
    };
  },
});
export const replayPrivate = operation({
  label: "replayPrivate",
  input: readPrivateCursor,
  depends: { currentUser, database },
  run: async ({ currentUser, database }, ctx) => {
    if (ctx.input.accountId !== currentUser.id) raise("StreamDenied", {});
    const [{ and, eq, gt, asc }, { event }] = await Promise.all([
      import("drizzle-orm"),
      import("../scaffold/backend/sync.schema.ts"),
    ]);
    return (
      await database
        .select()
        .from(event)
        .where(and(eq(event.stream, currentUser.id), gt(event.revision, ctx.input.after)))
        .orderBy(asc(event.revision))
        .limit(200)
    ).map(readFeatureEvent);
  },
});

import { pgTable, integer, text, boolean, index } from "drizzle-orm/pg-core";
import { user } from "./schema.ts";
export const todo = pgTable(
  "todo",
  {
    id: integer().primaryKey().generatedAlwaysAsIdentity(),
    ownerId: text()
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    title: text().notNull(),
    done: boolean().notNull().default(false),
  },
  (table) => [index("todo_owner_id").on(table.ownerId)],
);

import { operation } from "@tinker/core";
import { database } from "./database.ts";
import { currentUser } from "./auth.ts";
import { readTodoCommand } from "../contracts/commands.ts";
import { eventHistory } from "../scaffold/backend/events.ts";
import type { Todos } from "../contracts/todos.ts";
import type { Sync } from "../contracts/sync.ts";
import { raise } from "../errors.ts";
export const listTodos = operation({
  label: "listTodos",
  depends: { currentUser, database },
  run: async ({ currentUser, database }): Promise<Todos.Row[]> => {
    const [{ asc, eq }, { todo }] = await Promise.all([
      import("drizzle-orm"),
      import("./todos.schema.ts"),
    ]);
    return database
      .select({ id: todo.id, title: todo.title, done: todo.done })
      .from(todo)
      .where(eq(todo.ownerId, currentUser.id))
      .orderBy(asc(todo.id));
  },
});
export const changeTodo = operation({
  label: "changeTodo",
  input: readTodoCommand,
  depends: { currentUser, database, history: eventHistory },
  run: async ({ currentUser, database, history }, ctx) => {
    const [{ and, asc, eq }, { todo }, { execution }] = await Promise.all([
      import("drizzle-orm"),
      import("./todos.schema.ts"),
      import("../scaffold/backend/sync.schema.ts"),
    ]);
    await database.transaction(async (tx) => {
      await history.lock(tx, currentUser.id);
      if (await history.find(tx, ctx.input.executionId, currentUser.id)) return;
      const change = ctx.input.change;
      let changed = true;
      if (change.kind === "add")
        await tx.insert(todo).values({ ownerId: currentUser.id, title: change.title });
      else {
        const owned = and(eq(todo.id, change.id), eq(todo.ownerId, currentUser.id));
        const row = (await tx.select().from(todo).where(owned)).at(0);
        if (!row) raise("TodoMissing", {});
        if (change.kind === "delete") await tx.delete(todo).where(owned);
        else if (row.done !== change.done)
          await tx.update(todo).set({ done: change.done }).where(owned);
        else changed = false;
      }
      await tx.insert(execution).values({ id: ctx.input.executionId, stream: currentUser.id });
      const payloads: Sync.Payload[] = [];
      if (changed) {
        const rows = await tx
          .select({ id: todo.id, title: todo.title, done: todo.done })
          .from(todo)
          .where(eq(todo.ownerId, currentUser.id))
          .orderBy(asc(todo.id));
        payloads.push({ kind: "change", change: { kind: "todos", rows } });
      }
      payloads.push({ kind: "result", result: { kind: "complete", action: "todo" } });
      await history.append(tx, currentUser.id, ctx.input.executionId, payloads);
    });
    return { executionId: ctx.input.executionId };
  },
});

import { z } from "zod";
import { readProfileInput } from "./profile.ts";
import { readTodoChange } from "./todos.ts";
const profileCommand = z.object({ executionId: z.uuid(), profile: z.unknown() }).strict();
const todoCommand = z.object({ executionId: z.uuid(), change: z.unknown() }).strict();
export function readProfileCommand(raw: unknown) {
  const command = profileCommand.parse(raw);
  return { executionId: command.executionId, profile: readProfileInput(command.profile) };
}
export function readTodoCommand(raw: unknown) {
  const command = todoCommand.parse(raw);
  return { executionId: command.executionId, change: readTodoChange(command.change) };
}

import { z } from "zod";
import { raise } from "../errors.ts";
const credentials = z.object({
  mode: z.enum(["signup", "signin"]),
  name: z.string().max(80),
  email: z.email(),
  password: z.string().min(8),
});
export function readCredentials(raw: unknown) {
  const parsed = credentials.safeParse(raw);
  if (!parsed.success) raise("BadInput", { reason: "Check your email and password." });
  return parsed.data;
}

import { z } from "zod";
import { raise } from "../errors.ts";
export declare namespace Profile {
  type Value = { id: string; name: string; email: string; emailVerified: boolean };
  type Input = { name: string };
}
const profileInput = z.object({ name: z.string().trim().min(1).max(80) }).strict();
export function readProfileInput(raw: unknown): Profile.Input {
  const result = profileInput.safeParse(raw);
  if (!result.success) raise("BadInput", { reason: "Use a name with 1 to 80 letters." });
  return result.data;
}

import { z } from "zod";
import {
  eventEnvelope,
  snapshotEnvelope,
  batchEnvelope,
  bootstrapEnvelope,
  streamInput,
} from "../scaffold/sync.ts";
export { readExecution, readCursor, readPrivateCursor, readRetry } from "../scaffold/sync.ts";
export type { Sync } from "../scaffold/sync.ts";
export declare namespace FeatureSync {
  type Change = z.infer<typeof change>;
  type Result = z.infer<typeof result>;
  type Public = z.infer<typeof snapshot>["public"];
  type Private = NonNullable<z.infer<typeof snapshot>["private"]>;
}
const profileRecord = z.object({
  id: z.string(),
  name: z.string(),
  email: z.string(),
  emailVerified: z.boolean(),
});
const todoRecord = z.object({ id: z.number(), title: z.string(), done: z.boolean() });
const result = z.union([
  z.object({ kind: z.literal("complete"), action: z.enum(["counter", "todo"]) }),
  z.object({ kind: z.literal("complete"), action: z.literal("profile"), profileId: z.string() }),
